/**
 * `SetMachine` rather than `Machine`: a Kotlin variant named after its field's type shadows that type.
 */

public enum Command: Equatable, Hashable {
    
    case step(letter: Letter, by: Int8
    )
    case reset(letter: Letter
    )
    case stepEffect(effect: Effect, by: Int8
    )
    case resetEffect(effect: Effect
    )
    case setMachine(machine: Machine
    )
    case walk(by: Int8
    )
    case undo
    case redo





}

#if compiler(>=6)
extension Command: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCommand: FfiConverterRustBuffer {
    typealias SwiftType = Command

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Command {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .step(letter: try FfiConverterTypeLetter.read(from: &buf), by: try FfiConverterInt8.read(from: &buf)
        )
        
        case 2: return .reset(letter: try FfiConverterTypeLetter.read(from: &buf)
        )
        
        case 3: return .stepEffect(effect: try FfiConverterTypeEffect.read(from: &buf), by: try FfiConverterInt8.read(from: &buf)
        )
        
        case 4: return .resetEffect(effect: try FfiConverterTypeEffect.read(from: &buf)
        )
        
        case 5: return .setMachine(machine: try FfiConverterTypeMachine.read(from: &buf)
        )
        
        case 6: return .walk(by: try FfiConverterInt8.read(from: &buf)
        )
        
        case 7: return .undo
        
        case 8: return .redo
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Command, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .step(letter,by):
            writeInt(&buf, Int32(1))
            FfiConverterTypeLetter.write(letter, into: &buf)
            FfiConverterInt8.write(by, into: &buf)
            
        
        case let .reset(letter):
            writeInt(&buf, Int32(2))
            FfiConverterTypeLetter.write(letter, into: &buf)
            
        
        case let .stepEffect(effect,by):
            writeInt(&buf, Int32(3))
            FfiConverterTypeEffect.write(effect, into: &buf)
            FfiConverterInt8.write(by, into: &buf)
            
        
        case let .resetEffect(effect):
            writeInt(&buf, Int32(4))
            FfiConverterTypeEffect.write(effect, into: &buf)
            
        
        case let .setMachine(machine):
            writeInt(&buf, Int32(5))
            FfiConverterTypeMachine.write(machine, into: &buf)
            
        
        case let .walk(by):
            writeInt(&buf, Int32(6))
            FfiConverterInt8.write(by, into: &buf)
            
        
        case .undo:
            writeInt(&buf, Int32(7))
        
        
        case .redo:
            writeInt(&buf, Int32(8))
        
        }
    }
}


