 * Called on a link thread after every change of the screen, the connection or the round trip.
 */
public protocol DisplayListener: AnyObject, Sendable {
    
    func onDisplay(display: DisplayState) 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceDisplayListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceDisplayListener = UniffiVTableCallbackInterfaceDisplayListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceDisplayListener.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface DisplayListener: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceDisplayListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface DisplayListener: handle missing in uniffiClone")
            }
        },
        onDisplay: { (
            uniffiHandle: UInt64,
            display: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceDisplayListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onDisplay(
                     display: try FfiConverterTypeDisplayState_lift(display)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceDisplayListener> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceDisplayListener>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

